import{_ as s,C as r,o as n,c as t,j as i,E as e,a as o,a3 as d}from"./chunks/framework.C6R8kWFE.js";const z=JSON.parse(`{"title":"2-hafta","description":"","frontmatter":{"title":"2-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"10-sinf (Cyber)","link":"/10-sinf-cyber/"},"n":2,"bob":"I-bob · Kiberxavfsizlikka kirish","lessons":[{"g":4,"title":"CIA uchligi (1-qism): konfidensiallik, yaxlitlik va foydalanuvchanlik tamoyillari","lead":"CIA uchligi (1-qism): konfidensiallik, yaxlitlik va foydalanuvchanlik tamoyillari","link":"/10-sinf-cyber/hafta-02/dars-1","slide":"/slaydlar/10-sinf-cyber/hafta-02/dars-1.html","test":"/slaydlar/10-sinf-cyber/hafta-02/dars-1-test.html"},{"g":5,"title":"CIA uchligi (2-qism): CIA buzilish ssenariylari va MITM hujumlari","lead":"[!CAUTION]","link":"/10-sinf-cyber/hafta-02/dars-2","slide":"/slaydlar/10-sinf-cyber/hafta-02/dars-2.html","test":"/slaydlar/10-sinf-cyber/hafta-02/dars-2-test.html"},{"g":6,"title":"Xavfsizlikni anglash (1-qism): xavfsizlik tafakkuri va kuchli parollar siyosati","lead":"«Xavfsizlik o'ziga xos fikrlash tarzini talab qiladi. Yaxshi mutaxassislar do'konga kirsa qanday o'g'irlik qilish mumkinligini, kompyuter ko'rsa qanday zaiflik borligini o'ylamasdan turolmaydilar.» — **Bryus Shnayer**","link":"/10-sinf-cyber/hafta-02/dars-3","slide":"/slaydlar/10-sinf-cyber/hafta-02/dars-3.html","test":"/slaydlar/10-sinf-cyber/hafta-02/dars-3-test.html"}],"test":"/slaydlar/10-sinf-cyber/hafta-02/hafta-test.html"}},"headers":[],"relativePath":"10-sinf-cyber/hafta-02/index.md","filePath":"10-sinf-cyber/hafta-02/index.md"}`),h={name:"10-sinf-cyber/hafta-02/index.md"},k={class:"blk"},u={id:"uyga-vazifa",tabindex:"-1"};function y(f,a,c,m,b,g){const l=r("Icon");return n(),t("div",null,[i("div",k,[i("h2",u,[e(l,{name:"house"}),a[0]||(a[0]=o(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=d('<p>Ushbu haftada o&#39;tilgan darslar bo&#39;yicha mustaqil amaliy uyga vazifalar ro&#39;yxati:</p><hr><h3 id="_4-dars-cia-uchligi-konfidensiallik-yaxlitlik-va-foydalanuvchanlik-tamoyillari" tabindex="-1">4-dars. CIA uchligi: konfidensiallik, yaxlitlik va foydalanuvchanlik tamoyillari <a class="header-anchor" href="#_4-dars-cia-uchligi-konfidensiallik-yaxlitlik-va-foydalanuvchanlik-tamoyillari" aria-label="Permalink to &quot;4-dars. CIA uchligi: konfidensiallik, yaxlitlik va foydalanuvchanlik tamoyillari&quot;">​</a></h3><ol><li>O&#39;zingiz qiziqqan ikkita sohani tanlang (masalan: Elektron tijorat sayti va Tez tibbiy yordam dispetcherlik xizmati).</li><li>Ushbu ikki soha uchun CIA uchligini (C, I, A) taqqoslang va har biri uchun qaysi mezon birinchi o&#39;rinda turishini, nima sababdan shunday ekanligini 4-5 jumla bilan yozing.</li><li>Kompyuteringizda ixtiyoriy matnli fayl yarating va uning SHA-256 xeshini oling (<code>sha256sum</code> yoki <code>CertUtil -hashfile</code>). Matnga bitta probel yoki nuqta qo&#39;shib qayta xesh oling va ikkala natijani daftaringizga ko&#39;chirib solishtiring.</li></ol><hr><h3 id="_5-dars-cia-buzilish-ssenariylari-va-mitm-hujumlari" tabindex="-1">5-dars. CIA buzilish ssenariylari va MITM hujumlari <a class="header-anchor" href="#_5-dars-cia-buzilish-ssenariylari-va-mitm-hujumlari" aria-label="Permalink to &quot;5-dars. CIA buzilish ssenariylari va MITM hujumlari&quot;">​</a></h3><ol><li>O&#39;rtadagi odam (MITM) hujumi qanday qilib bir vaqtning o&#39;zida ham Konfidensiallikka, ham Yaxlitlikka putur yetkazishi mumkinligini ssenariy asosida tushuntiring.</li><li>Nima sababdan kafe yoki aeroportlardagi ochiq jamoat Wi-Fi tarmoqlarida parollarni kiritish xavfli va nima uchun bunday holatlarda VPN ishlatish zarur?</li><li>Tarmoq kommutatorlarida Dynamic ARP Inspection (DAI) texnologiyasi qanday ishlashini konspektdan foydalanib yozma bayon eting.</li></ol><hr><h3 id="_6-dars-xavfsizlik-tafakkuri-va-kuchli-parollar-siyosati" tabindex="-1">6-dars. Xavfsizlik tafakkuri va kuchli parollar siyosati <a class="header-anchor" href="#_6-dars-xavfsizlik-tafakkuri-va-kuchli-parollar-siyosati" aria-label="Permalink to &quot;6-dars. Xavfsizlik tafakkuri va kuchli parollar siyosati&quot;">​</a></h3><ol><li>Xavfsizlik tafakkurining 5 ta tamoyilidan (What could go wrong, Adversarial, Defensive, Assume breach, Know assets) birini tanlang va unga kundalik hayotingizdan bitta misol keltiring.</li><li><code>haveibeenpwned.com/Passwords</code> xizmatiga kiring (yoki Kaspersky Password Checker) va ilgari ishlatgan oddiy so&#39;zli parollaringiz (masalan: <code>123456</code>, <code>qwerty2020</code>) necha marta buzilgan bazalarda topilganini tekshiring.</li><li>O&#39;zingiz uchun kamida 14 belgidan iborat, katta-kichik harflar, sonlar va belgilarni o&#39;z ichiga olgan namunaviy kuchli parol formulasini ishlab chiqing (masalan: sevimli she&#39;r yoki iboraning bosh harflari asosida: <code>M@kt@b2025#Oqish</code>).</li></ol><hr>',11))])])}const p=s(h,[["render",y]]);export{z as __pageData,p as default};
